    }
}

void fftTransform(vector<long long>& array, int length, int direction) {
    bitSwap(array, length);
    for (int size = 2; size <= length; size <<= 1) {
        long long wlen = fastPower(G, (MOD - 1) / size);
        if (direction == -1) wlen = fastPower(wlen, MOD - 2);
        for (int start = 0; start < length; start += size) {
